import React from 'react';
import {useEffect,useState,useRef} from 'react';
import {Globe2,Plane,Plus,Users,User,ArrowUpRight,ArrowRight,ChevronRight,ChevronDown,MapPin,Search,ShieldCheck,Ghost,Eye,X,Check,Navigation,Footprints,Bike,Car,TrainFront,Coffee,Heart,Compass,Camera,Music,MessageCircle,Send,Bell,Settings,Flag,Clock,LocateFixed,Leaf,Sparkles,Sun,LoaderCircle,Lock,LogOut,CheckCheck,RefreshCw} from 'lucide-react';
import WorldMap from './WorldMap';
import '@fontsource/dm-sans/latin-400.css';import '@fontsource/dm-sans/latin-500.css';import '@fontsource/dm-sans/latin-600.css';import '@fontsource/dm-sans/latin-700.css';import '@fontsource/plus-jakarta-sans/latin-500.css';import '@fontsource/plus-jakarta-sans/latin-600.css';import '@fontsource/plus-jakarta-sans/latin-700.css';
const IDS=['alex','sarah','jamie','maya','chris'];
const MODES=[['walk','Walk',Footprints],['cycle','Cycle',Bike],['drive','Drive',Car],['transit','Transit',TrainFront]];
const CIRCLES=[{id:'close',name:'Close friends',emoji:'✦',color:'lavender',description:'Your everyday people',members:5},{id:'partner',name:'Partner',emoji:'♡',color:'peach',description:'A little closer, always',members:2},{id:'family',name:'Family',emoji:'⌂',color:'sage',description:'Home is a group of people',members:3}];
function Avatar({id,size=44,className=''}){return <img className={`avatar ${className}`} width={size} height={size} src={`/avatars/${id}.svg`} alt={id?`${id[0].toUpperCase()+id.slice(1)}'s avatar`:''}/>;}
function Fresh({at}){const s=Math.max(0,Math.floor((Date.now()-at)/1000));return <span className="fresh"><i className={s>60?'stale':''}/>{s<30?'Updated just now':s<60?`Updated ${s}s ago`:s<1800?`Updated ${Math.floor(s/60)} min ago`:'Location unavailable'}</span>;}
function Toggle({enabled,onClick,label}){return <button role="switch" aria-checked={enabled} aria-label={label} className={`toggle ${enabled?'on':''}`} onClick={onClick}><span/></button>;}
function Chip({children,className=''}){return <span className={`chip ${className}`}>{children}</span>;}
function Empty({icon:Icon=Leaf,title,children}){return <div className="empty"><Icon size={28}/><h3>{title}</h3><p>{children}</p></div>;}
async function api(path,body){const res=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const result=await res.json();if(!res.ok)throw new Error(result.error||'Something went wrong. Please try again.');return result;}
export default function App(){
 const [w,setW]=useState(null),[tab,setTab]=useState('world'),[panel,setPanel]=useState(null),[filter,setFilter]=useState('all'),[night,setNight]=useState(false),[route,setRoute]=useState(null),[toast,setToast]=useState(null),[identity,setIdentity]=useState(false),[query,setQuery]=useState(''),[busy,setBusy]=useState(false),[mapReady,setMapReady]=useState(false);
 const active=useRef(null);active.current=panel;const routeRef=useRef(route);routeRef.current=route;
 const announce=(text)=>{setToast(text);};
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(null),4500);return()=>clearTimeout(t);},[toast]);
 const refresh=()=>api('/api/world').then(setW).catch(e=>announce(e.message));
 useEffect(()=>{refresh();const i=setInterval(refresh,2500);return()=>clearInterval(i);},[]);
 async function act(body){setBusy(true);try{const result=await api('/api/action',body);setW(result);return result;}catch(e){announce(e.message);return null;}finally{setBusy(false);}}
 async function switchTo(id,keepPanel=false){try{setW(await api('/api/identity',{id}));setIdentity(false);setRoute(null);setFilter('all');if(!keepPanel)setPanel(null);announce(`You're exploring as ${id[0].toUpperCase()+id.slice(1)} · demo`);}catch(e){announce(e.message);}}
 const openPerson=async p=>{setPanel({type:'person',id:p.id});await act({action:'view',person:p.id});};
 async function loadRoute({person,place,mode='walk',name,grantId}){try{const r=await api(`/api/route?${person?'person='+person:'place='+place}&mode=${mode}`);setRoute({...r,person,place,name,grantId});setPanel({type:'navigation',person,place,name,grantId,mode});setTab('world');}catch(e){announce(e.message);}}
 useEffect(()=>{
  if(!w||!route?.person)return;
  const p=w.people.find(p=>p.id===route.person);
  if(p?.location?.precision!=='precise'){setRoute(null);if(panel?.type==='navigation')setPanel(null);announce('Precise sharing ended. Back to area-only visibility.');}else if(route.targetCoordinate && Date.now()-route.updatedAt>=20000){const [a,b]=p.location.coordinate,[c,d]=route.targetCoordinate;const meters=Math.hypot((a-c)*84250,(b-d)*111320);if(meters>35)loadRoute({...route,mode:route.mode});}
 },[w]);
 if(!w)return <div className="loading-app"><img src="/icon.svg" width="56"/><h1>kindred<span>✦</span></h1><p>A little closer to your people.</p><LoaderCircle className="spin" size={22}/></div>;
 const nearby=w.people.filter(p=>p.nearby),incoming=w.requests.filter(r=>r.to===w.viewer&&r.status==='pending'),grants=w.grants.filter(g=>g.viewer===w.viewer),outgoing=w.grants.filter(g=>g.owner===w.viewer),agreedPoint=w.requests.find(r=>r.kind==='point'&&r.status==='accepted'&&(r.from===w.viewer||r.to===w.viewer));
 const person=panel?.id?w.people.find(p=>p.id===panel.id):null;
 const go=(next)=>{setTab(next);setPanel(null);setRoute(null);};
 const showPrivacy=()=>{setTab('you');setPanel(null);};
 const request=async(p,kind='meetup',place)=>{const result=await act({action:'request',person:p.id,kind,place:place?.id});if(result)setPanel({type:'sent',person:p,kind,place});};
 const toggleGhost=async()=>{const result=await act({action:'ghost',enabled:!w.me.hidden});if(result){setRoute(null);announce(result.me.hidden?'You’re hidden. All location sharing has stopped.':'You’re visible to trusted friends, approximately.');}};
 const navItems=[['world','World',Globe2],['trips','Trips',Plane],['create','Create',Plus],['circles','Circles',Users],['you','You',User]];
 return <div className={`app ${night?'dark-world':''}`}>
  <aside className="nav-rail"><a className="brand-icon" aria-label="Kindred World" href="#" onClick={e=>{e.preventDefault();go('world');}}><img src="/icon.svg" alt="Kindred"/></a><nav>{navItems.map(([id,label,Icon])=><button key={id} className={`${tab===id?'active':''} ${id==='create'?'create-nav':''}`} onClick={()=>id==='create'?setPanel({type:'create'}):go(id)} aria-label={label}><Icon size={22} strokeWidth={1.7}/><span>{label}</span>{id==='world'&&<i/>}</button>)}</nav><div className="rail-bottom"><button aria-label="Privacy Center" onClick={showPrivacy}><ShieldCheck size={21}/></button><button aria-label="Change demo identity" onClick={()=>setIdentity(!identity)}><Avatar id={w.viewer} size={37}/></button></div></aside>
  <div className="app-body"><header className="topbar"><a className="wordmark" href="#" onClick={e=>{e.preventDefault();go('world');}}>kindred<span>✦</span></a><div className="header-divider"/><div className="header-context">Your people, a little closer.</div><div className="topbar-actions"><Chip className="demo-tag">Interactive demo</Chip><button className={`ghost-button ${w.me.hidden?'hidden':''}`} onClick={toggleGhost}><Ghost size={17}/><span>{w.me.hidden?'You are hidden':'Ghost mode'}</span><i className={w.me.hidden?'enabled':''}/></button><button className={`notification-button ${incoming.length?'has-unread':''}`} aria-label="Notifications" onClick={()=>setPanel({type:'inbox'})}><Bell size={19}/>{incoming.length>0&&<b>{incoming.length}</b>}</button><button className="identity-button" onClick={()=>setIdentity(!identity)} aria-label="Change demo identity"><Avatar id={w.viewer} size={33}/><span>{w.me.name}</span><ChevronDown size={13}/></button></div></header>
  {identity&&<div className="identity-popover"><small>EXPLORE THE DEMO AS</small><p>Switch people to give real approval.</p>{IDS.map(id=><button key={id} onClick={()=>switchTo(id)}><Avatar id={id} size={30}/><span>{id[0].toUpperCase()+id.slice(1)}</span>{id===w.viewer&&<Check size={16}/>}</button>)}</div>}
  <main className="main-space">
   <div className="world-stage"><WorldMap people={w.people} self={w.selfLocation} places={w.places} onPerson={openPerson} onPlace={p=>setPanel({type:'place',place:p})} route={route} night={night} onNight={()=>setNight(!night)} filter={filter} onReady={()=>setMapReady(true)}/></div>
   {tab==='world'&&<><aside className="people-panel"><div className="panel-heading"><div><span className="eyebrow">A LITTLE CLOSER</span><h1>Your world<span>✳</span></h1></div><button className="plain icon-button" aria-label="View activity" onClick={()=>setPanel({type:'inbox'})}><Bell size={19}/></button></div><p className="intro-copy">Good places. Better company.</p><div className="sharing-note" onClick={showPrivacy} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&showPrivacy()}><ShieldCheck size={17}/><span>{w.me.hidden?'You are hidden from everyone':'Your location is approximate'}</span><ChevronRight size={14}/></div>
    <label className="people-search"><Search size={17}/><input placeholder="Find your people" aria-label="Find your people" value={query} onChange={e=>setQuery(e.target.value)}/><span>⌘ K</span></label>
    <div className="nearby-heading"><h2>{query?'Your people':'Around you'}<span>{nearby.length}</span></h2><Chip className="live"><i/>Now</Chip></div><p className="subtle nearby-description">A good day for a little hello.</p>
    <div className="people-list">{w.people.filter(p=>query?p.name.toLowerCase().includes(query.toLowerCase()):p.nearby).map(p=><button key={p.id} className="person-row" onClick={()=>openPerson(p)}><div className={`avatar-wrap ${p.moment?'moment-ring':''}`}><Avatar id={p.id} size={48}/><span>{p.emoji}</span></div><div className="person-copy"><strong>{p.name}</strong><small>{p.status}</small><span>{p.nearby?'Within ~1 km':p.hidden?'Location hidden':p.location?.area||'Location unavailable'}</span></div><ArrowUpRight size={17}/></button>)}{!(query?w.people.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())).length:nearby.length)&&<Empty title={w.me.hidden?'A little space for you':'No one nearby'}>{w.me.hidden?'Ghost Mode is on. Turn it off whenever you’re ready.':'Try searching for a friend.'}</Empty>}</div>
    <button className="coffee-banner" onClick={()=>nearby[0]?request(nearby[0],'coffee'):announce('No nearby friends are available right now.')}><span className="coffee-illustration">☕<i>✧</i></span><span><strong>Make a little time.</strong><small>Someone nearby might be free.</small></span><ArrowRight size={18}/></button>
    <div className="section-label"><h2>On the way</h2><button onClick={()=>setPanel({type:'journey-create'})}><Plus size={16}/></button></div>
    {w.journeys.filter(j=>j.status!=='cancelled').length?w.journeys.filter(j=>j.status!=='cancelled').map(j=><button key={j.id} className="journey-preview" onClick={()=>setPanel({type:'journey',id:j.id})}><Avatar id={j.owner} size={34}/><div><strong>{j.ownerName} → {j.destination.name}</strong><small>{j.status==='arrived'?'Arrived safely ✓':`${j.status} · ~${j.eta} min`}</small><div className="progress"><i style={{width:`${j.progress*100}%`}}/></div></div><ChevronRight size={15}/></button>):<button className="journey-empty" onClick={()=>setPanel({type:'journey-create'})}><span className="journey-icon"><Navigation size={18}/></span><span><strong>Going somewhere?</strong><small>Let them know when you’re there.</small></span><ArrowUpRight size={17}/></button>}
    <div className="section-label circles-label"><h2>Your circles</h2><button onClick={()=>go('circles')}><ArrowUpRight size={16}/></button></div><div className="circle-pills">{CIRCLES.map(c=><button key={c.id} className={filter===c.id?'active':''} onClick={()=>setFilter(filter===c.id?'all':c.id)}><span>{c.emoji}</span>{c.name}</button>)}</div><div className="sidebar-foot"><span>Little moments. Real connections.</span><span>✧</span></div>
   </aside>
   <section className="world-hud"><div className="world-top"><div className="location-pill"><span className="location-dot"/><button onClick={()=>setPanel({type:'city'})}>New York, NY<ChevronDown size={13}/></button><span className="time-caption">A city full of your people</span></div><button className="privacy-pill" onClick={showPrivacy}><ShieldCheck size={14}/><span>Private by nature</span></button></div>
    <div className="map-title"><span className="eyebrow">THE WORLD, WITH YOUR PEOPLE IN IT</span><h2>Less “where are you?”<br/>More <span>“see you soon.”</span></h2><div className="map-filters"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}><Users size={14}/>Everyone</button><button className={filter==='nearby'?'active':''} onClick={()=>setFilter('nearby')}><LocateFixed size={14}/>Nearby<span>{nearby.length}</span></button><button className={filter==='close'?'active':''} onClick={()=>setFilter('close')}>✦ Close friends</button></div></div>
    {incoming.length>0&&<button className="incoming-banner" onClick={()=>setPanel({type:'incoming',id:incoming[0].id})}><Avatar id={incoming[0].from} size={34}/><span><strong>{incoming[0].fromName} wants to {incoming[0].kind==='location'?'see your precise location':'meet you'} 👋</strong><small>Your choice. Your location stays private.</small></span><ChevronRight size={19}/></button>}
    {grants.length>0&&!route&&<button className="incoming-banner approved-banner" onClick={()=>loadRoute({person:grants[0].owner,name:grants[0].ownerName,grantId:grants[0].id})}><Navigation size={23}/><span><strong>{grants[0].ownerName} approved temporary sharing</strong><small>Tap to choose how you’ll get there.</small></span><ArrowRight size={18}/></button>}
    {agreedPoint&&!route&&<button className="incoming-banner approved-banner" onClick={()=>loadRoute({place:agreedPoint.place.id,name:agreedPoint.place.name})}><Coffee size={23}/><span><strong>You both agreed on {agreedPoint.place.name}</strong><small>Your starting positions stay private. Preview a route.</small></span><ArrowRight size={18}/></button>}
    {w.me.hidden&&<div className="ghost-map-banner"><Ghost size={22}/><span><strong>A little time to yourself.</strong><small>You’re hidden. All location sharing is stopped.</small></span><button onClick={toggleGhost}>Go visible</button></div>}
    <div className="world-bottom"><button className="pulse-card" onClick={()=>setPanel({type:'pulse'})}><div className="pulse-symbol"><Sparkles size={19}/></div><div><span>WORLD PULSE <i/></span><strong>{w.moments.length?`${w.moments[0].ownerName} captured a little moment`:'Your world is quietly keeping up'}</strong><small>{w.moments[0]?.place||'Only shared with trusted people'}</small></div><ArrowUpRight size={18}/></button><div className="world-legend"><span><i/>Area-only locations</span><button onClick={()=>setPanel({type:'city'})}>{mapReady?'Real geography · 3D World':'Loading real geography…'}<ArrowUpRight size={11}/></button></div></div>
    <button className="mobile-nearby" onClick={()=>setPanel({type:'nearby'})}><div className="avatar-stack">{nearby.slice(0,3).map(p=><Avatar id={p.id} key={p.id} size={32}/>)}</div><span><strong>{nearby.length} friends nearby <span>👋</span></strong><small>{w.me.hidden?'You are hidden':'A little hello goes a long way.'}</small></span><ChevronRight size={19}/></button>
   </section></>}
   {tab==='trips'&&<section className="page-view"><div className="page-top"><div><span className="eyebrow">MAKE THE MOST OF BEING TOGETHER</span><h1>Away, together<span>✈</span></h1><p>Split up. Find your own thing. Come back together.</p></div><button className="primary" onClick={()=>setPanel({type:'trip-info'})}><Plus size={17}/>Start a trip</button></div><div className="trip-feature"><div className="trip-art"><div className="skyline"><i/><i/><i/><i/><i/><i/><i/><i/></div><div className="trip-art-copy"><Chip>THE CITY IS YOURS</Chip><h2>New York<br/><em>kind of weekend.</em></h2><span>Little plans, big memories.</span></div><span className="trip-sticker">NYC<br/>↗</span></div><div className="trip-details"><Chip className="live"><i/>Active demo trip</Chip><h2>{w.trip.name}</h2><p>Five friends. One city. All the freedom to explore.</p><div className="trip-member-list">{w.trip.memberNames.map(p=><div key={p.id}><Avatar id={p.id} size={42}/><strong>{p.name}{p.id===w.viewer?' (you)':''}</strong><small>{p.joined?'Joined ✓':'Not joined yet'}</small></div>)}</div><div className="privacy-callout"><ShieldCheck size={18}/><span>Areas by default. Everyone chooses to join.<br/>No one’s exact starting point is shared.</span></div><div className="button-row">{w.trip.joined.includes(w.viewer)?<><button className="primary" onClick={()=>setPanel({type:'regroup'})}><Users size={17}/>Regroup</button><button className="secondary" onClick={()=>{act({action:'trip-leave'});announce('You left the trip.');}}>Leave trip</button></>:<button className="primary" onClick={()=>act({action:'trip-join'})}><Check size={17}/>Join this trip</button>}</div></div></div>{w.trip.proposal&&<div className="proposal-card"><div className="proposal-place">{w.trip.proposal.place.emoji}</div><div><span className="eyebrow">LET’S COME BACK TOGETHER</span><h3>Meet at {w.trip.proposal.place.name}</h3><p>{w.trip.proposal.accepted.length} of {w.trip.joined.length} accepted · {w.trip.proposal.status==='agreed'?'Everyone’s in!':'Waiting for your people'}</p></div>{w.trip.proposal.status==='agreed'?<button className="primary" onClick={()=>loadRoute({place:w.trip.proposal.place.id,name:w.trip.proposal.place.name})}>Navigate<Navigation size={16}/></button>:<><button className="primary" onClick={()=>act({action:'trip-respond',accept:true})}>Accept<Check size={16}/></button><button className="secondary" onClick={()=>act({action:'trip-respond',accept:false})}>Not now</button></>}</div>}<div className="memory-teaser"><Leaf size={24}/><div><h3>Keep memories, not movement history.</h3><p>The moments you choose to share stay with your people.</p></div><button onClick={()=>setPanel({type:'pulse'})}>View Moments<ArrowUpRight size={15}/></button></div></section>}
   {tab==='circles'&&<section className="page-view"><div className="page-top"><div><span className="eyebrow">GOOD PEOPLE, GOOD COMPANY</span><h1>Your inner world<span>✦</span></h1><p>A place for the people you choose to keep close.</p></div></div><div className="circle-grid">{CIRCLES.map(c=><button className={`circle-card ${c.color}`} key={c.id} onClick={()=>{setFilter(c.id);go('world');}}><span className="circle-symbol">{c.emoji}</span><ArrowUpRight className="card-arrow" size={21}/><h2>{c.name}</h2><p>{c.description}</p><div className="avatar-stack">{IDS.filter(id=>id===w.viewer||w.people.find(p=>p.id===id)?.circle.includes(c.id)).slice(0,5).map(id=><Avatar key={id} id={id} size={36}/>)}</div><small>Approximate sharing · trusted people</small></button>)}</div><div className="trusted-card"><ShieldCheck size={31}/><div><h3>Your world isn’t for everyone.</h3><p>Location is only shared with trusted relationships. Block or remove someone in their detail card to revoke access immediately.</p></div><button className="secondary" onClick={showPrivacy}>Privacy Center<ArrowUpRight size={16}/></button></div></section>}
   {tab==='you'&&<section className="page-view privacy-page"><div className="page-top"><div><span className="eyebrow">YOUR WORLD, YOUR CHOICE</span><h1>Peace of mind<span>♡</span></h1><p>Know exactly what you’re sharing. Change it anytime.</p></div><Chip><ShieldCheck size={14}/>Privacy Center</Chip></div><div className="privacy-grid"><div className="privacy-main"><div className={`visibility-card ${w.me.hidden?'is-hidden':''}`}><div className="visibility-icon">{w.me.hidden?<Ghost size={26}/>:ShieldCheck&&<ShieldCheck size={26}/>}</div><div><span className="eyebrow">YOUR LOCATION</span><h2>{w.me.hidden?'You are hidden.':'Approximate by default.'}</h2><p>{w.me.hidden?'Nobody can see your location, nearby status, or Journey.':'Your trusted friends see an area, never your exact spot.'}</p></div><Toggle label="Ghost Mode" enabled={w.me.hidden} onClick={toggleGhost}/></div><div className="privacy-settings"><div><div><Ghost size={20}/><span><strong>Ghost Mode</strong><small>Stop all location exposure instantly</small></span></div><Chip>{w.me.hidden?'ON':'OFF'}</Chip></div><div><div><LocateFixed size={20}/><span><strong>Nearby visibility</strong><small>Let friends know when you’re within ~1 km</small></span></div><Toggle label="Nearby visibility" enabled={w.me.nearby} onClick={()=>act({action:'nearby',enabled:!w.me.nearby})}/></div><div><div><Users size={20}/><span><strong>Who can see me</strong><small>{w.me.hidden?'No one while you’re hidden':`${w.people.filter(p=>!p.hidden).length} trusted friends · approximate areas`}</small></span></div><button onClick={()=>setPanel({type:'visibility'})}>Manage<ChevronRight size={14}/></button></div><div><div><Eye size={20}/><span><strong>Viewed You</strong><small>Intentional detail views, grouped by person</small></span></div><button onClick={()=>setPanel({type:'views'})}>{w.views.length?`${w.views.length} people`:'View'}<ChevronRight size={14}/></button></div></div><div className="precise-card"><div className="section-label"><h2>Precise permissions</h2><Chip>{outgoing.length} active</Chip></div>{outgoing.length?outgoing.map(g=><div className="permission-row" key={g.id}><Avatar id={g.viewer} size={40}/><span><strong>{g.viewerName} can navigate to you</strong><small>{g.untilMeet?'Until you meet · ':''}{Math.ceil((g.expiresAt-Date.now())/60000)} min remaining</small></span><button className="danger-text" onClick={()=>act({action:'revoke',id:g.id})}>Stop sharing</button></div>):<div className="calm-note"><Lock size={18}/><span>No one can see your precise location.</span></div>}<p className="privacy-caption">Precise when mutually needed. Automatically private afterward.</p></div><button className="stop-all" onClick={async()=>{const r=await act({action:'ghost',enabled:true});if(r){setRoute(null);announce('All location sharing stopped. You are hidden.');}}}><Ghost size={19}/>Stop all location sharing</button></div><div className="privacy-side"><div className="profile-card"><Avatar id={w.viewer} size={75}/><h2>{w.me.name}</h2><p>{w.me.emoji} {w.me.status}</p><button className="secondary" onClick={()=>setPanel({type:'status'})}>Set your status<Sparkles size={14}/></button></div><div className="privacy-small-card"><h3>Active sharing</h3><div><Navigation size={17}/><span>Journeys</span><b>{w.journeys.filter(j=>j.owner===w.viewer&&!['arrived','cancelled'].includes(j.status)).length}</b></div><div><Plane size={17}/><span>Trips you’ve joined</span><b>{w.trip.joined.includes(w.viewer)?1:0}</b></div><div><Users size={17}/><span>Meet Ups</span><b>{w.grants.filter(g=>g.purpose==='meetup').length}</b></div><button onClick={()=>setPanel({type:'blocked'})}>Blocked people<ChevronRight size={15}/></button></div><div className="demo-note"><Sparkles size={16}/><h3>A safe space to try it.</h3><p>All people, movement, and permissions are simulated. No device location is collected.</p><button onClick={async()=>{await act({action:'reset'});setRoute(null);announce('Demo reset. A fresh little world.');}}>Reset demo<RefreshCw size={13}/></button></div></div></div></section>}
  </main></div>
  <nav className="mobile-nav">{navItems.map(([id,label,Icon])=><button key={id} className={`${tab===id?'active':''} ${id==='create'?'create-nav':''}`} onClick={()=>id==='create'?setPanel({type:'create'}):go(id)} aria-label={label}><Icon size={21} strokeWidth={1.7}/>{id!=='create'&&<span>{label}</span>}</button>)}</nav>
  {panel&&<><div className="sheet-scrim" onClick={()=>setPanel(null)}/><section className={`sheet ${['create','city','status','moment-create','journey-create','trip-info'].includes(panel.type)?'center-sheet':''}`} role="dialog" aria-modal="true" aria-label={panel.type==='person'?`${person?.name||'Person'} details`:panel.type.replaceAll('-',' ')}><div className="sheet-handle"/><button className="sheet-close" aria-label="Close panel" onClick={()=>setPanel(null)}><X size={19}/></button><div className="sheet-content" key={`${panel.type}-${panel.id||''}`}>
   {panel.type==='person'&&person&&<><div className="person-detail-head"><div className={`detail-avatar ${person.moment?'moment-ring':''}`}><Avatar id={person.id} size={86}/><span>{person.emoji}</span></div><span className="eyebrow">ONE OF YOUR PEOPLE</span><h2>{person.name}</h2><p>{person.status}</p><Chip className={person.hidden?'':'live'}>{person.hidden?<Ghost size={13}/>:<MapPin size={13}/>} {person.hidden?'Taking some space':person.nearby?'Nearby · within ~1 km':person.location?.area||'Location unavailable'}</Chip></div><div className="area-card"><ShieldCheck size={22}/><div><strong>{person.location?.precision==='precise'?'Temporarily precise':person.hidden?'Location is hidden':'An area, not an exact spot'}</strong><small>{person.location?.precision==='precise'?`Explicitly shared · ${Math.ceil((person.location.expiresAt-Date.now())/60000)} min remaining`:'Zooming in won’t reveal more detail.'}</small></div></div>{person.location&&<Fresh at={person.location.updatedAt}/>}<div className="detail-actions"><button className="primary full" disabled={person.hidden||busy} onClick={()=>request(person)}><Users size={18}/>Meet Up<ArrowRight size={17}/></button><button className="secondary full" disabled={person.hidden||busy} onClick={()=>setPanel({type:'halfway',id:person.id})}><Coffee size={18}/>Meet halfway</button><div className="button-row"><button className="secondary" disabled={person.hidden} onClick={()=>request(person,'location')}><MapPin size={16}/>Request location</button><button className="secondary" onClick={()=>{setPanel({type:'message',id:person.id});}}><MessageCircle size={16}/>Message</button></div></div>{person.music&&<div className="music-card"><div className="album-art"><Music size={24}/></div><div><small>IN THEIR OWN LITTLE WORLD</small><strong>{person.music.split(' · ')[0]}</strong><span>{person.music.split(' · ')[1]}</span></div><div className="equalizer"><i/><i/><i/></div></div>}<button className="text-row" onClick={()=>setPanel({type:'pulse',id:person.id})}><Camera size={18}/><span>View Moments</span><ChevronRight size={16}/></button><div className="detail-transparency"><Eye size={14}/> {person.name} can see that you opened their details.</div><div className="detail-block"><button onClick={async()=>{await act({action:'block',person:person.id});setPanel(null);announce(`${person.name} is blocked. Location access revoked.`);}}>Block {person.name}</button><button onClick={async()=>{await act({action:'remove',person:person.id});setPanel(null);announce('Friendship removed. Location access revoked.');}}>Remove friendship</button></div></>}
   {panel.type==='create'&&<><span className="eyebrow">A LITTLE SOMETHING TOGETHER</span><h2>What’s the plan?</h2><p className="sheet-intro">More real life. Less checking in.</p><div className="quick-actions">{[[Users,'Meet Up','Find a little time for your people','nearby'],[Navigation,'Share Journey','They’ll know when you arrive','journey-create'],[Camera,'Moment','Something worth keeping','moment-create'],[MapPin,'Share Location','Your choice, for a little while','share-location'],[Music,'Music','Set a little soundtrack','music'],[Sparkles,'Status','Let them know your mood','status'],[Plane,'Start Trip','A shared world for your adventure','trip-info'],[Heart,'Your circles','Keep your people close','circles']].map(([Icon,title,sub,type])=><button key={type} onClick={()=>type==='circles'?(go('circles')):setPanel({type})}><span><Icon size={20}/></span><div><strong>{title}</strong><small>{sub}</small></div><ArrowUpRight size={17}/></button>)}</div></>}
   {panel.type==='nearby'&&<><span className="eyebrow">A GOOD DAY FOR A HELLO</span><h2>{nearby.length} friends nearby 👋</h2><p className="sheet-intro">Within ~1 km, without sharing exact locations.</p>{nearby.map(p=><button className="person-row" key={p.id} onClick={()=>openPerson(p)}><Avatar id={p.id} size={48}/><div className="person-copy"><strong>{p.name}</strong><small>{p.emoji} {p.status}</small><span>Within ~1 km</span></div><ArrowUpRight size={18}/></button>)}{!nearby.length&&<Empty title="A quiet little world">Turn off Ghost Mode to see who’s nearby.</Empty>}</>}
   {panel.type==='sent'&&<><div className="request-illustration"><Avatar id={w.viewer} size={70}/><span>↗</span><Avatar id={panel.person.id} size={70}/></div><span className="eyebrow">A LITTLE HELLO, SENT</span><h2>{panel.kind==='point'?`Meet at ${panel.place.name}?`:panel.kind==='coffee'?'Coffee sounds good.':panel.kind==='location'?'A request, not a reveal.':'See you soon, maybe.'}</h2><p className="sheet-intro">{panel.person.name} received your {panel.kind==='location'?'precise location':'Meet Up'} request. Their location stays approximate until they choose to share.</p><div className="pending-state"><Clock size={17}/>Waiting for {panel.person.name}’s choice</div><div className="demo-explain"><Sparkles size={17}/><p>Try both sides of the demo. Switch to {panel.person.name} to respond as the recipient.</p></div><button className="primary full" onClick={async()=>{const name=panel.person.id;const r=await api('/api/identity',{id:name});setW(r);setRoute(null);setPanel({type:'incoming',id:r.requests.find(x=>x.to===name&&x.status==='pending')?.id});}}>Explore {panel.person.name}’s view<ArrowRight size={17}/></button></>}
   {panel.type==='incoming'&&<Incoming w={w} id={panel.id} act={act} onDone={(from)=>setPanel({type:'approved',from})}/>}
   {panel.type==='approved'&&<><div className="success-symbol"><Check size={32}/></div><span className="eyebrow">YOUR CHOICE, ALWAYS</span><h2>You’re in control.</h2><p className="sheet-intro">Your response was sent. You can revoke any precise permission in Privacy Center, and it expires automatically.</p><button className="primary full" onClick={async()=>{await switchTo(panel.from);}}>Back to {panel.from[0].toUpperCase()+panel.from.slice(1)}’s World<ArrowRight size={17}/></button><button className="secondary full" onClick={()=>{setPanel(null);showPrivacy();}}>Review my sharing<ShieldCheck size={17}/></button></>}
   {panel.type==='navigation'&&<><span className="eyebrow">A LITTLE CLOSER, STEP BY STEP</span><h2>Meet {panel.name}</h2>{w.people.find(p=>p.id===panel.person)?.moving&&<Chip className="live"><Footprints size={12}/>{panel.name} is moving</Chip>}<p className="sheet-intro">{panel.person?'Temporarily shared with permission.':'A public place you can both find.'}</p><div className="route-summary"><span><Navigation size={25}/></span><div><strong>{route?.minutes||'–'}<small>min</small></strong><p>{route?.meters?`${route.meters>=1000?(route.meters/1000).toFixed(1)+' km':route.meters+' m'}`:'Finding a route'} · demo estimate</p></div><Chip className="live"><i/>On the way</Chip></div><div className="travel-modes">{MODES.map(([id,label,Icon])=><button className={panel.mode===id?'active':''} key={id} onClick={()=>loadRoute({...panel,mode:id})}><Icon size={21}/><span>{label}</span></button>)}</div><div className="navigation-tip"><Footprints size={20}/><span><strong>A route through real streets</strong><small>Demo routing isn’t suitable for live navigation. Transit and driving estimates are simulated.</small></span></div>{panel.person&&<button className="text-row" onClick={async()=>{const result=await act({action:'simulate-move',person:panel.person});if(result)announce('Movement simulated. Route refreshes after the 20-second update interval.');}}><Footprints size={18}/><span>Simulate {panel.name} moving</span><ArrowRight size={15}/></button>}
    {panel.person&&<div className="privacy-callout"><ShieldCheck size={19}/><span>Sharing automatically returns to approximate when the session ends or expires.</span></div>}<button className="primary full" onClick={async()=>{if(panel.grantId)await act({action:'complete',id:panel.grantId});setRoute(null);setPanel(null);announce('You made it! Temporary sharing has ended.');}}><CheckCheck size={18}/>We’ve met</button><button className="secondary full" onClick={()=>{setRoute(null);setPanel(null);}}>Close navigation</button></>}
   {panel.type==='halfway'&&<Halfway w={w} person={panel.id} onChoose={place=>request(w.people.find(p=>p.id===panel.id),'point',place)}/>}
   {panel.type==='regroup'&&<Regroup act={act} onDone={()=>{setPanel(null);announce('Meeting point proposed. Each joined member can accept in Trips.');}}/>}
   {panel.type==='journey-create'&&<JourneyForm w={w} act={act} onDone={j=>setPanel({type:'journey',id:j.id})}/>}
   {panel.type==='journey'&&<JourneyDetail w={w} id={panel.id} act={act} onClose={()=>setPanel(null)}/>}
   {panel.type==='views'&&<><span className="eyebrow">A LITTLE TRANSPARENCY</span><h2>Viewed You</h2><p className="sheet-intro">Passive map views stay quiet. Opening your details is recorded here.</p>{w.views.length?w.views.sort((a,b)=>b.at-a.at).map(v=><div className="view-row" key={v.viewer}><Avatar id={v.viewer} size={43}/><div><strong>{v.name}</strong><small>{v.count>1?`Viewed your details ${v.count} times today`:'Viewed your details'}</small></div><span>{Date.now()-v.at<60000?'Just now':`${Math.floor((Date.now()-v.at)/60000)}m ago`}</span></div>):<Empty icon={Eye} title="No detail views yet">Your World can be viewed without a notification. Only intentional detail views appear here.</Empty>}<div className="privacy-callout"><ShieldCheck size={18}/><span>View history never grants location access.</span></div></>}
   {panel.type==='inbox'&&<><span className="eyebrow">FROM YOUR PEOPLE</span><h2>A little hello</h2><p className="sheet-intro">Requests and arrival updates. Quiet when it should be.</p>{incoming.map(r=><button key={r.id} className="inbox-row" onClick={()=>setPanel({type:'incoming',id:r.id})}><Avatar id={r.from} size={45}/><span><strong>{r.fromName}{r.kind==='location'?' requested your location':r.kind==='coffee'?' is free for coffee ☕':' wants to meet you 👋'}</strong><small>Respond with your choice</small></span><ChevronRight size={17}/></button>)}{w.notifications.map(n=><div className="inbox-row" key={n.id}><CheckCheck size={24}/><span><strong>{n.text}</strong><small>Journey sharing ended automatically</small></span></div>)}{!incoming.length&&!w.notifications.length&&<Empty icon={Bell} title="All quiet here">Your people’s requests and arrival updates will appear here.</Empty>}</>}
   {panel.type==='place'&&<><div className="place-detail-art">{panel.place.emoji}<span>✧</span></div><Chip>{panel.place.type}</Chip><h2>{panel.place.name}</h2><p className="sheet-intro">{panel.place.description}</p><div className="area-card"><MapPin size={20}/><div><strong>{panel.place.label}</strong><small>A real, public meeting point in New York.</small></div></div><button className="primary full" onClick={()=>loadRoute({place:panel.place.id,name:panel.place.name})}><Navigation size={18}/>Navigate here</button><button className="secondary full" onClick={()=>setPanel({type:'regroup'})}><Users size={17}/>Suggest to trip</button></>}
   {panel.type==='city'&&<><span className="eyebrow">REAL PLACES, SHARED MOMENTS</span><h2>A New York state of mind.</h2><p className="sheet-intro">Explore Lower Manhattan, from the Financial District to the waterfront. The roads and building footprints are real.</p><div className="geo-stats"><div><strong>999</strong><span>real buildings</span></div><div><strong>1,531</strong><span>road segments</span></div><div><strong>0</strong><span>GPS collected</span></div></div><div className="privacy-callout"><ShieldCheck size={18}/><span>People and movement are simulated. Bundled geography works without a map API key.</span></div><p className="small-copy">MapLibre · OpenStreetMap contributors · Natural Earth · vis.gl. Building heights are from the demo dataset; geography is not a live survey.</p><button className="primary full" onClick={()=>setPanel(null)}>Back to your World<Globe2 size={17}/></button></>}
   {panel.type==='status'&&<StatusForm w={w} act={act} done={()=>{setPanel(null);announce('Your people can see your new status.');}}/>}
   {panel.type==='music'&&<><span className="eyebrow">YOUR LITTLE SOUNDTRACK</span><h2>What’s your mood?</h2><p className="sheet-intro">Mock music for the demo. No streaming account needed.</p>{[['🎧','Birds of a Feather'],['🎶','Sunday Morning'],['🌙','Midnight City']].map(([emoji,title])=><button key={title} className="text-row" onClick={async()=>{await act({action:'status',text:`Listening to ${title}`,emoji});setPanel(null);announce('Music status shared with your people.');}}><Music size={20}/><span>{title}</span><Plus size={17}/></button>)}<button className="secondary full" onClick={async()=>{await act({action:'status',text:'Exploring',emoji:'🌿'});setPanel(null);}}>Turn off music status</button></>}
   {panel.type==='moment-create'&&<MomentForm w={w} act={act} done={()=>{setPanel({type:'pulse'});announce('Moment shared with your selected people.');}}/>}
   {panel.type==='pulse'&&<><span className="eyebrow">LITTLE MOMENTS, REAL CONNECTIONS</span><h2>{panel.id?'Their little world':'World Pulse'}<span className="title-spark">✧</span></h2><p className="sheet-intro">A glimpse of what your people are up to.</p>{w.moments.filter(m=>!panel.id||m.owner===panel.id).map(m=><article className="moment-card" key={m.id}><div><Avatar id={m.owner} size={35}/><span><strong>{m.ownerName}</strong><small>{Math.max(1,Math.round((Date.now()-m.createdAt)/60000))}m ago · selected people</small></span></div><div className="moment-art"><span>☀</span><div>little city<br/><em>big feelings.</em></div><i>✳</i></div><p>{m.text}</p>{m.place&&<small><MapPin size={12}/>{m.place}</small>}</article>)}{!w.moments.filter(m=>!panel.id||m.owner===panel.id).length&&<Empty icon={Camera} title="No moments just yet">Some things are better lived first.</Empty>}<button className="secondary full" onClick={()=>setPanel({type:'moment-create'})}><Plus size={17}/>Share a Moment</button></>}
   {panel.type==='visibility'&&<><span className="eyebrow">ONLY THE PEOPLE YOU CHOOSE</span><h2>Who can see me</h2><p className="sheet-intro">Trusted friends see approximate areas. Precise access requires a separate, temporary approval.</p>{w.people.map(p=><div className="view-row" key={p.id}><Avatar id={p.id} size={42}/><div><strong>{p.name}</strong><small>{w.me.hidden?'No location shared':outgoing.some(g=>g.viewer===p.id)?'Temporary precise sharing':'Approximate area only'}</small></div><button className="text-link" onClick={async()=>{await act({action:'block',person:p.id});announce(`${p.name} blocked.`);}}>Block</button></div>)}</>}
   {panel.type==='blocked'&&<><span className="eyebrow">YOUR BOUNDARIES MATTER</span><h2>Blocked people</h2><p className="sheet-intro">Blocked people can’t request or receive your location.</p>{w.me.blocked.length?w.me.blocked.map(id=><div className="view-row" key={id}><Avatar id={id} size={40}/><strong>{id[0].toUpperCase()+id.slice(1)}</strong><button className="text-link" onClick={()=>act({action:'unblock',person:id})}>Unblock</button></div>):<Empty icon={ShieldCheck} title="No blocked people">Manage people from their detail card.</Empty>}</>}
   {panel.type==='share-location'&&<><span className="eyebrow">PRECISE WHEN MUTUALLY NEEDED</span><h2>Choose your person.</h2><p className="sheet-intro">Request a temporary connection. The recipient chooses whether to share.</p>{w.people.filter(p=>!p.hidden).map(p=><button className="person-row" key={p.id} onClick={()=>request(p,'location')}><Avatar id={p.id} size={43}/><div className="person-copy"><strong>{p.name}</strong><small>Ask for explicit approval</small></div><ArrowRight size={17}/></button>)}</>}
   {panel.type==='message'&&<><span className="eyebrow">A LITTLE HELLO</span><h2>Say hi to {person?.name}</h2><p className="sheet-intro">Messaging is outside this demo’s focus. Try a coffee invite to coordinate without exchanging locations.</p><button className="primary full" onClick={()=>request(person,'coffee')}><Coffee size={18}/>Free for coffee?</button></>}
   {panel.type==='trip-info'&&<><span className="eyebrow">A SHARED LITTLE ADVENTURE</span><h2>One city. Your people.</h2><p className="sheet-intro">The MVP includes one demo travel group: a New York weekend. Each person can join, explore separately, and accept a public regroup point.</p><div className="privacy-callout"><Plane size={21}/><span>No automatic opt-in. Switch demo identities to experience joining and regroup approvals.</span></div><button className="primary full" onClick={()=>go('trips')}>Open demo trip<ArrowRight size={17}/></button></>}
  </div></section></>}
  {toast&&<div className="toast" role="status"><Check size={17}/><span>{toast}</span><button aria-label="Dismiss notification" onClick={()=>setToast(null)}><X size={14}/></button></div>}
 </div>;
}
function Incoming({w,id,act,onDone}){
 const [duration,setDuration]=useState('until-meet'),[choice,setChoice]=useState('allow');const r=w.requests.find(r=>r.id===id&&r.to===w.viewer);
 if(!r||r.status!=='pending')return <Empty icon={Check} title="Request handled">This request is no longer pending.</Empty>;
 if(r.kind==='point')return <><div className="request-illustration"><Avatar id={r.from} size={75}/><span>☕</span></div><span className="eyebrow">YOU’RE EXPLORING AS {w.me.name.toUpperCase()}</span><h2>{r.fromName} suggested {r.place.name}.</h2><p className="sheet-intro">A public meeting point. Your exact starting positions remain private.</p><div className="area-card"><MapPin size={21}/><div><strong>{r.place.label}</strong><small>{r.place.description}</small></div></div><button className="primary full" onClick={async()=>{const result=await act({action:'respond',id:r.id,decision:'public'});if(result)onDone(r.from);}}>Agree to meet here<Check size={16}/></button><button className="secondary full" onClick={async()=>{const result=await act({action:'respond',id:r.id,decision:'decline'});if(result)onDone(r.from);}}>Not now</button></>;
 return <><div className="request-illustration"><Avatar id={r.from} size={75}/><span>👋</span></div><span className="eyebrow">YOU’RE EXPLORING AS {w.me.name.toUpperCase()}</span><h2>{r.kind==='location'?`${r.fromName} requested your location.`:r.kind==='coffee'?`${r.fromName} is nearby. Coffee?`:`${r.fromName} wants to meet you.`}</h2><p className="sheet-intro">Nothing precise is shared unless you say yes.</p><div className="approval-choices"><button className={choice==='allow'?'selected':''} onClick={()=>setChoice('allow')}><Navigation size={19}/><span><strong>Allow navigation</strong><small>Temporarily share your precise location</small></span><i>{choice==='allow'&&<Check size={12}/>}</i></button>{r.kind!=='location'&&<button className={choice==='halfway'?'selected':''} onClick={()=>setChoice('halfway')}><Coffee size={19}/><span><strong>Meet at a public place</strong><small>Keep both starting positions private</small></span><i>{choice==='halfway'&&<Check size={12}/>}</i></button>}</div>{choice==='allow'&&<><label className="form-label">FOR HOW LONG?</label><div className="duration-options">{[['15m','15 minutes'],['30m','30 minutes'],['1h','1 hour'],['until-meet','Until we meet']].filter(([id])=>r.kind!=='location'||id!=='until-meet').map(([id,label])=><button key={id} className={duration===id?'selected':''} onClick={()=>setDuration(id)}>{label}{duration===id&&<Check size={13}/>}</button>)}</div><p className="small-copy">“Until we meet” expires after one hour at the latest.</p></>}<button className="primary full" onClick={async()=>{const result=await act({action:'respond',id:r.id,decision:choice,duration:duration==='until-meet'&&r.kind==='location'?'15m':duration});if(result)onDone(r.from);}}><Check size={17}/>{choice==='allow'?'Allow temporary sharing':'Choose public meeting points'}</button><button className="secondary full" onClick={async()=>{const result=await act({action:'respond',id:r.id,decision:'decline'});if(result)onDone(r.from);}}>Not now</button></>;
}
function Halfway({w,person,onChoose}){
 const [suggestions,setSuggestions]=useState(null),[error,setError]=useState(null),[selected,setSelected]=useState(null);const p=w.people.find(p=>p.id===person),r=w.requests.find(r=>r.from===w.viewer&&r.to===person&&r.status==='accepted'&&r.decision==='halfway');
 useEffect(()=>{api('/api/halfway?person='+person).then(setSuggestions).catch(e=>setError(e.message));},[person]);
 return <><span className="eyebrow">A GOOD PLACE TO COME TOGETHER</span><h2>A little halfway.</h2><p className="sheet-intro">Public places between you and {p?.name}. Neither exact starting point is revealed.</p><div className="privacy-callout"><ShieldCheck size={19}/><span>Travel times are simulated. Suggest a public place; both people agree before meetup navigation starts.</span></div>{error&&<p className="error">{error}</p>}{suggestions?.map(s=><button key={s.place.id} className={`suggestion-card ${selected===s.place.id?'selected':''}`} onClick={()=>setSelected(s.place.id)}><span className="place-emoji">{s.place.emoji}</span><div><strong>{s.place.name}</strong><small>{s.place.label}</small><span>You · ~{s.yourMinutes} min <i/> {p?.name} · ~{s.theirMinutes} min</span></div><i className="choice-check">{selected===s.place.id?<Check size={14}/>:<Plus size={14}/>}</i></button>)}<button className="primary full" disabled={!selected} onClick={()=>onChoose(suggestions.find(s=>s.place.id===selected).place)}>Suggest meeting point<Send size={17}/></button><p className="small-copy">Public-place navigation doesn’t grant access to anyone’s precise location.</p></>;
}
function Regroup({act,onDone}){
 const [options,setOptions]=useState(null),[selected,setSelected]=useState('oculus'),[error,setError]=useState(null);
 useEffect(()=>{api('/api/regroup').then(setOptions).catch(e=>setError(e.message));},[]);
 return <><span className="eyebrow">EXPLORE APART. COME BACK TOGETHER.</span><h2>Time to regroup?</h2><p className="sheet-intro">A real public spot, with approximate travel times for participating friends.</p>{error?<p className="error">{error}</p>:options?.map(o=><button key={o.place.id} className={`regroup-option ${selected===o.place.id?'selected':''}`} onClick={()=>setSelected(o.place.id)}><div><span>{o.place.emoji}</span><strong>{o.place.name}</strong>{selected===o.place.id?<Check size={17}/>:<Plus size={17}/>}</div><div className="regroup-times">{o.members.map(p=><span key={p.id}><Avatar id={p.id} size={23}/>{p.name}<small>~{p.minutes}m</small></span>)}</div></button>)}<button className="primary full" disabled={!options} onClick={async()=>{const r=await act({action:'regroup',place:selected});if(r)onDone();}}>Propose to group<Send size={16}/></button><p className="small-copy">Each joined member must accept. Hidden members’ travel times stay private.</p></>;
}
function JourneyForm({w,act,onDone}){
 const [place,setPlace]=useState('waterfront'),[audience,setAudience]=useState(w.people.filter(p=>!p.hidden).map(p=>p.id));
 return <><span className="eyebrow">“TELL ME WHEN YOU’RE THERE,” HANDLED.</span><h2>Share your Journey.</h2><p className="sheet-intro">Your people can follow your progress, without seeing your exact position.</p><label className="form-label" htmlFor="destination">WHERE ARE YOU HEADING?</label><select id="destination" value={place} onChange={e=>setPlace(e.target.value)}>{w.places.map(p=><option key={p.id} value={p.id}>{p.emoji} {p.name}</option>)}</select><label className="form-label">SHARE WITH YOUR PEOPLE</label><Audience people={w.people} selected={audience} onChange={setAudience}/><div className="privacy-callout"><ShieldCheck size={18}/><span>Only your destination, progress, and approximate ETA are shared. Sharing ends on arrival.</span></div><button className="primary full" onClick={async()=>{const r=await act({action:'journey',place,audience});if(r)onDone(r.journeys.filter(j=>j.owner===w.viewer).at(-1));}}><Navigation size={17}/>Start Journey</button><p className="small-copy">Demo journey takes about 75 seconds. No device GPS needed.</p></>;
}
function JourneyDetail({w,id,act,onClose}){
 const j=w.journeys.find(j=>j.id===id);if(!j)return <Empty title="Journey unavailable">It’s private or no longer shared with you.</Empty>;
 const arrived=j.status==='arrived';return <><div className="journey-detail-hero"><Avatar id={j.owner} size={70}/><span>{arrived?'✓':'→'}</span><div>{j.destination.emoji}</div></div><span className="eyebrow">{arrived?'THERE, SAFE AND SOUND':'ONE LESS “WHERE ARE YOU?”'}</span><h2>{j.ownerName} {arrived?'arrived.':'is on the way.'}</h2><p className="sheet-intro">{j.destination.name}</p><div className="journey-big-status"><strong>{arrived?'✓':`~${j.eta}`}<small>{arrived?'Arrived':'min away'}</small></strong><Chip className="live">{j.status}</Chip></div><div className="progress big"><i style={{width:`${j.progress*100}%`}}/></div><div className="journey-stages">{['Leaving','On the way','Nearby','Arrived'].map((s,i)=><span className={j.progress>=[0,.08,.8,1][i]?'done':''} key={s}><i/>{s}</span>)}</div><div className="privacy-callout"><ShieldCheck size={18}/><span>{arrived?'Journey sharing is finished. Normal area-only visibility resumes.':'Progress is shared, precise location is private.'}</span></div><h3 className="small-heading">{j.owner===w.viewer?'Who can follow':'Shared with'}</h3><div className="audience-faces">{j.audience.map(id=><div key={id}><Avatar id={id} size={35}/><span>{id[0].toUpperCase()+id.slice(1)}</span></div>)}</div>{j.owner===w.viewer&&!['arrived','cancelled'].includes(j.status)&&<button className="secondary full" onClick={async()=>{await act({action:'cancel-journey',id:j.id});onClose();}}>Stop Journey sharing</button>}<p className="small-copy">Simulated journey. Arrival updates appear in selected people’s inboxes.</p></>;
}
function Audience({people,selected,onChange}){return <div className="audience-select">{people.map(p=><button key={p.id} className={selected.includes(p.id)?'selected':''} onClick={()=>onChange(selected.includes(p.id)?selected.filter(x=>x!==p.id):[...selected,p.id])}><Avatar id={p.id} size={30}/><span>{p.name}</span><i>{selected.includes(p.id)&&<Check size={12}/>}</i></button>)}</div>;}
function StatusForm({w,act,done}){const [text,setText]=useState(w.me.status),[emoji,setEmoji]=useState(w.me.emoji);return <><span className="eyebrow">LET YOUR PEOPLE KNOW YOUR MOOD</span><h2>Your little status.</h2><p className="sheet-intro">A feeling, a plan, a little invitation.</p><div className="status-presets">{[['☕','Free for coffee'],['🚶','On a little walk'],['🌿','Taking it slow'],['🎧','In my own world'],['💭','Up for a hello']].map(([e,t])=><button key={t} className={text===t?'selected':''} onClick={()=>{setText(t);setEmoji(e);}}>{e}<span>{t}</span></button>)}</div><input className="form-input" aria-label="Your status" maxLength={60} value={text} onChange={e=>setText(e.target.value)}/><button className="primary full" onClick={async()=>{const r=await act({action:'status',text,emoji});if(r)done();}}>Share status<Sparkles size={16}/></button></>;}
function MomentForm({w,act,done}){const [text,setText]=useState(''),[audience,setAudience]=useState(w.people.filter(p=>p.circle.includes('close')).map(p=>p.id)),[place,setPlace]=useState('');return <><span className="eyebrow">A LITTLE SOMETHING WORTH KEEPING</span><h2>Share a Moment.</h2><p className="sheet-intro">For your people. Never a public location feed.</p><textarea placeholder="What made you smile today?" aria-label="Moment text" maxLength={280} value={text} onChange={e=>setText(e.target.value)}/><label className="form-label" htmlFor="moment-place">PUBLIC PLACE (OPTIONAL)</label><select id="moment-place" value={place} onChange={e=>setPlace(e.target.value)}><option value="">Keep location out of it</option>{w.places.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><label className="form-label">ONLY THESE PEOPLE</label><Audience people={w.people} selected={audience} onChange={setAudience}/><button className="primary full" disabled={!text.trim()||!audience.length} onClick={async()=>{const r=await act({action:'moment',text,audience,place});if(r)done();}}>Share Moment<Send size={16}/></button></>;}
